    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount == 0);
        // Only the owner can call sendTo; we assume the deployer is owner
        bool reverted = false;
        try c.sendTo(receiver, amount) {
            // no revert
        } catch {
            reverted = true;
        }
        assertTrue(reverted);
    }
}

